import { PlaneGeometry, Mesh, Group } from 'three/webgpu';
import { texture as textureNode } from 'three/tsl';
import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new Group();

  // Load image texture from URL (cached by ctx.textureLoader)
  const imageTexture = ctx.textureLoader.load(config.imageUrl);

  // Create plane geometry sized to atlas region aspect ratio (512:320)
  const aspectRatio = 512 / 320;
  const planeWidth = 1.0;
  const planeHeight = planeWidth / aspectRatio;
  const planeGeometry = new PlaneGeometry(planeWidth, planeHeight);

  // Create material using TSL texture node
  const colorNode = textureNode(imageTexture);
  const material = new MeshBasicNodeMaterial({
    colorNode,
    transparent: true,
  });

  // Create and add textured plane
  const plane = new Mesh(planeGeometry, material);
  group.add(plane);

  // Render text content via fontAtlas
  if (config.textContent && config.textContent.text) {
    const textMesh = ctx.fontAtlas.renderText(
      config.textContent.text,
      {
        fontSize: config.textContent.size || 0.34,
        weight: config.textContent.weight || 400,
        font: 'Lora',
      }
    );
    // Position text above card center
    textMesh.position.set(0, planeHeight * 0.2, 0.01);
    group.add(textMesh);
  }

  // Apply cinematic primitives if specified
  if (config.cinematicPrimitives && config.cinematicPrimitives.length > 0) {
    for (const primitive of config.cinematicPrimitives) {
      ctx.primitives[primitive.name](group, primitive.params);
    }
  }

  // Setup cleanup
  group.userData.cleanup = () => {
    planeGeometry.dispose();
    material.dispose();
  };

  // Setup event handlers
  group.userData.handlers = {};

  return group;
}
